import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

# Test candidate values for x, where x = 6m + 5 and x > 5
candidates = [11, 17, 23]
results = {}

for x in candidates:
    # We need to check if x^5 + x - 2 is a power of 2
    value = x**5 + x - 2
    is_pow2 = is_power_of_two(value)
    k = None
    if is_pow2:
        k = int(math.log2(value))
    results[x] = {
        "value": value,
        "is_power_of_two": is_pow2,
        "k": k
    }

print(results)
